P(15,'climbing_stairs','Climbing Stairs','Подъём по лестнице','Сколькими способами можно подняться на n ступеней шагами 1 или 2?','Последний шаг приходит с n−1 либо n−2; для нулевой лестницы есть один пустой путь.','O(n);O(n)',[({'n':5},8),({'n':0},1)])
P(15,'minimum_coins','Minimum Coin Combination','Минимальное число монет','Найдите минимум монет для amount при неограниченном запасе, либо -1.','Для каждой суммы попробуйте последнюю монету и возьмите минимальное известное состояние.','O(amount·c);O(amount)',[({'coins':[1,3,4],'amount':6},2),({'coins':[2],'amount':3},-1)])
P(15,'matrix_pathways','Matrix Pathways','Пути в прямоугольнике','Посчитайте пути из верхнего левого в нижний правый угол, двигаясь вправо и вниз.','Число путей в клетку равно сумме путей сверху и слева.','O(rc);O(rc)',[({'rows':3,'cols':3},6),({'rows':1,'cols':4},1)])
P(15,'burglary','Neighborhood Burglary','Несоседние дома','Найдите максимальную сумму, не выбирая соседние дома.','В каждой позиции сравните пропуск и выбор вместе с ответом до предыдущего соседа.','O(n);O(n)',[({'a':[2,7,9,3,1]},12),({'a':[]},0)])
P(15,'lcs','Longest Common Subsequence','Общая подпоследовательность','Найдите длину LCS двух строк; символы не обязаны стоять рядом.','Совпадение продолжает диагональ; иначе выбирается лучший ответ без одного из символов.','O(mn);O(mn)',[({'s':'abcde','t':'ace'},3),({'s':'abc','t':'def'},0)])
P(15,'longest_palindrome','Longest Palindrome in a String','Самая длинная палиндромная подстрока','Верните первую самую длинную палиндромную подстроку.','Края равны, а внутренний диапазон уже является палиндромом; заполняйте по длине.','O(n²);O(n²)',[({'s':'babad'},'bab'),({'s':'cbbd'},'bb')])
P(15,'maximum_subarray','Maximum Subarray Sum','Максимальная сумма подмассива','Найдите максимальную сумму непустого непрерывного подмассива.','Продлевайте предыдущий отрезок только если это лучше начала с текущего числа.','O(n);O(n)',[({'a':[-2,1,-3,4,-1,2,1,-5,4]},6),({'a':[-3,-1,-2]},-1)])
P(15,'knapsack','0/1 Knapsack','Рюкзак 0/1','Каждый предмет можно взять один раз: максимизируйте ценность при ограничении веса.','Сравните пропуск предмета и его выбор из предыдущей строки таблицы.','O(nW);O(nW)',[({'weights':[1,3,4],'values':[15,20,30],'capacity':4},35),({'weights':[2],'values':[5],'capacity':1},0)])
P(15,'largest_square','Largest Square in a Matrix','Самый большой квадрат','Верните площадь максимального квадрата из единиц.','Сторона квадрата равна 1 плюс минимум трёх соседних сторон.','O(rc);O(rc)',[({'grid':[[1,0,1],[1,1,1],[1,1,1]]},4),({'grid':[[0]]},0)])

P(16,'jump_end','Jump to the End','Достижимость конца','Число задаёт максимальную длину прыжка: достижим ли последний индекс?','Сохраняйте самую дальнюю достижимую позицию; разрыв за ней преодолеть нельзя.','O(n);O(1)',[({'a':[2,3,1,1,4]},True),({'a':[3,2,1,0,4]},False)])
P(16,'gas_stations','Gas Stations','Круговой маршрут','Найдите стартовый индекс, позволяющий проехать круг, или -1.','Если накопленный остаток отрицателен, ни один старт внутри пройденного отрезка не подходит.','O(n);O(1)',[({'gas':[1,2,3,4,5],'cost':[3,4,5,1,2]},3),({'gas':[2,3,4],'cost':[3,4,3]},-1)])
P(16,'candies','Candies','Конфеты по рейтингу','Каждому нужна хотя бы одна конфета; более высокий рейтинг соседа требует больше конфет.','Два прохода независимо учитывают левого и правого соседа.','O(n);O(n)',[({'a':[1,0,2]},5),({'a':[1,2,2]},4)])

P(17,'sort_linked','Sort Linked List','Сортировка связного списка','Отсортируйте связный список за O(n log n).','Разделите список по середине и объедините отсортированные половины.','O(n log n);O(log n)',[({'a':[4,2,1,3]},[1,2,3,4]),({'a':[]},[])],'linked')
P(17,'sort_array','Sort Array','Сортировка слиянием','Отсортируйте массив по возрастанию.','Слияние двух упорядоченных половин выбирает меньший из текущих элементов.','O(n log n);O(n)',[({'a':[5,2,3,1]},[1,2,3,5]),({'a':[2,2,1]},[1,2,2])])
P(17,'kth_largest','Kth Largest Integer','k-е наибольшее число','Найдите k-й элемент в убывающем порядке с учётом повторений.','Quickselect оставляет только часть, содержащую позицию n−k.','O(n) в среднем, O(n²) худшее;O(1)',[({'a':[3,2,1,5,6,4],'k':2},5),({'a':[2,2,1],'k':2},2)])
P(17,'dutch_flag','Dutch National Flag','Три цвета','Упорядочьте массив из 0, 1 и 2 за один проход.','Области до low и после high уже готовы; после обмена с high текущая позиция ещё не проверена.','O(n);O(1)',[({'a':[2,0,2,1,1,0]},[0,0,1,1,2,2]),({'a':[1,1]},[1,1])])

P(18,'hamming_weights','Hamming Weights of Integers','Количество единичных битов','Верните число единиц для всех целых от 0 до n.','Число i наследует ответ i>>1 и добавляет младший бит.','O(n);O(n)',[({'n':5},[0,1,1,2,1,2]),({'n':0},[0])])
P(18,'lonely_integer','Lonely Integer','Одиночное число','Все числа, кроме одного, встречаются дважды: найдите одиночное.','XOR одинаковых чисел равен нулю, порядок операций неважен.','O(n);O(1)',[({'a':[4,1,2,1,2]},4),({'a':[0]},0)])
P(18,'swap_bits','Swap Odd and Even Bits','Обмен соседних битов','Поменяйте соседние биты неотрицательного 32-битного числа.','Разделите чётные и нечётные позиции масками и сдвиньте навстречу друг другу.','O(1), 32 бита;O(1)',[({'n':23},43),({'n':0},0)])

P(19,'spiral_traversal','Spiral Traversal','Обход по спирали','Прочитайте прямоугольную матрицу по часовой стрелке от верхнего левого угла.','Четыре границы сжимаются после прохода по соответствующей стороне.','O(rc);O(1) без ответа',[({'grid':[[1,2,3],[4,5,6],[7,8,9]]},[1,2,3,6,9,8,7,4,5]),({'grid':[[1,2,3]]},[1,2,3])],'grid')
P(19,'reverse_integer','Reverse 32-Bit Integer','Разворот 32-битного числа','Разверните десятичные цифры знакового 32-битного числа; при переполнении верните 0.','Извлекайте младшую цифру остатком от деления и добавляйте её к ответу.','O(log |n|);O(1)',[({'n':-120},-21),({'n':1534236469},0)],'array')
P(19,'collinear_points','Maximum Collinear Points','Максимум точек на прямой','Найдите максимальное число различных точек на одной прямой.','Для каждой опорной точки считайте нормализованные пары (dy,dx); знак фиксируется.','O(n²);O(n)',[({'points':[[1,1],[2,2],[3,3],[1,3]]},3),({'points':[[0,0],[0,1],[0,2]]},3)])
P(19,'josephus','The Josephus Problem','Задача Иосифа Флавия','Из круга людей 1…n удаляется каждый k-й; найдите номер выжившего.','После удаления задача меньшего размера пересчитывается с циклическим сдвигом.','O(n);O(1)',[({'n':5,'k':2},3),({'n':1,'k':3},1)])
P(19,'triangle_numbers','Triangle Numbers','Чётное число в треугольнике','Вершина треугольника — 1; ниже каждая клетка равна сумме трёх соседей сверху, отсутствующий сосед равен 0. Найдите позицию первого чётного числа строки n≥3 (нумерация с 1).','Для ответа достаточно чётности первых четырёх позиций: их рисунок повторяется каждые четыре строки.','O(1);O(1)',[({'n':7},2),({'n':8},3)],'triangle')

EASY = {'pair_sum_sorted','is_palindrome_valid','shift_zeros','pair_sum_unsorted','linked_reversal','linked_intersection','palindromic_list','linked_loop','linked_midpoint','insertion_index','valid_parentheses','remove_duplicates','range_sum','invert_tree','balanced_tree','climbing_stairs','hamming_weights','lonely_integer'}
HARD = {'lru_cache','uniform_substring','median_arrays','evaluate_expression','window_maximum','stream_median','maximum_tree_path','board_words','word_transform','merge_communities','shortest_path','n_queens','lcs','knapsack','gas_stations','collinear_points'}
for lesson in LESSONS:
    lesson['difficulty'] = 'Easy' if lesson['id'] in EASY else 'Hard' if lesson['id'] in HARD else 'Medium'
